INSERT INTO `sa_article` (`category`,`tags`,`views`,`id`,`category_id`,`dept_id`,`is_link`,`image`,`summary`,`status`,`updated_by`,`title`,`author`,`tenant_id`,`content`,`cover_image`,`is_hot`,`created_by`,`create_time`,`describe`,`sort`,`link_url`,`update_time`,`delete_time`) VALUES (NULL,NULL,5,1,1,3,2,'https://www.news.cn/tech/20251203/51066a5dc41545fa849d49423770ad70/2025120351066a5dc41545fa849d49423770ad70_202512037a03214ec26c4f029d6e1599d07c3779.png',NULL,1,1,'科技为农业强国建设插上腾飞之翼','新华网',1,'<p style="text-align: justify;"> &nbsp; &nbsp; &nbsp; &nbsp;“平均亩产1209.1公斤，这标志着全国首个两百万亩玉米‘吨粮田’成功创建。”金秋时节，新疆伊犁哈萨克自治州传来喜讯。这一纪录的诞生，离不开中国农业科学院研发的“玉米密植高产精准调控技术”支撑。依托该技术，位于伊犁的200余万亩玉米高产田亩保苗株数从传统的不足5000株提升到7000—8000株，玉米收获穗数大幅提升。</p><p style="text-align: justify;">　　这只是我国科技强农、粮食增产增收的一个缩影。“十四五”以来，我国粮食总产量始终保持在1.3万亿斤以上。2024年粮食总产量更是首次突破1.4万亿斤，比2020年增产740亿斤。</p><p style="text-align: justify;">　　习近平总书记强调，发展现代农业，建设农业强国，必须依靠科技进步，让科技为农业现代化插上腾飞的翅膀。</p><p style="text-align: justify;">　　“十四五”规划提出，完善农业科技创新体系，创新农技推广服务方式，建设智慧农业。5年来，在科技创新的强劲支撑下，14亿人的饭碗端得更牢、农业现代化水平显著提升、产业新动能持续增强，农业强国建设迈上新台阶。</p><p style="text-align: justify;">　　科技铸“芯”，夯实大国粮仓之基</p><p style="text-align: justify;">　　国以农为本，农以种为先，种子被誉为农业的“芯片”。前不久，四川省富顺县水稻百亩超高产攻关片进行实割实测，再生稻亩产达到494.81公斤，加上此前测产中稻亩产807.13公斤，合计亩产突破1300公斤。取得这一成绩的背后，是“甬优4949”等高产突破性品种的选育和“中稻+再生稻”生产模式的推广。</p><p style="text-align: justify;">　　水稻是我国第一大口粮。“十四五”时期全国多地选育出一批水稻突破性品种：安徽农业大学水稻栽培团队推广自育水稻品种，帮助当地农户水稻亩产增至800公斤；湖南杂交水稻研究中心选育出“西子3号”，推动解决部分受重金属污染地区“镉大米”问题；国家耐盐碱水稻技术创新中心培育出“箐两优3261”，填补了我国华南滨海盐碱区暂无强耐盐、多抗、优质杂交稻品种的空白……</p><p style="text-align: justify;">　　习近平总书记指出，中国人的饭碗要牢牢端在自己手中，就必须把种子牢牢攥在自己手里。</p><p style="text-align: justify;">　　作为我国另一大口粮，小麦育种的创新步伐也不断提速。2025年，西北农林科技大学一次性通过国家审定12个新品种，覆盖半冬性、冬性、春性类型，在抗倒伏等方面实现全面突破。这些为不同生态区“量身定制”的品种，在丰富我国小麦品种的同时，也大幅提升了小麦产能潜力。截至目前，西农小麦系列品种累计推广面积已达18亿亩，为保障国家粮食安全提供了坚实的种源支撑。</p><p style="text-align: justify;">　　“十四五”以来，我国深入实施种业振兴行动，育成了一批生产急需的重大品种，选育出优质高产水稻、节水抗病小麦、机收籽粒玉米、高油高产大豆等急需品种，农作物自主选育品种面积占比超过了95%，做到了“中国粮”主要用“中国种”。</p><p style="text-align: justify;">　　“去年全国粮食亩产394.7公斤，比‘十三五’末提高了12.5公斤，单产提升对我国粮食产量增长的贡献超过60%，有些年份会超过80%。”农业农村部党组书记、部长韩俊表示，“十四五”以来，农业农村部深入实施国家粮食安全战略，“以我为主、立足国内、确保产能、适度进口、科技支撑”，坚持产量产能、生产生态、增产增收一起抓，强化藏粮于地、藏粮于技，全方位夯实粮食安全根基。</p><p style="text-align: justify;">　　智慧提“效”，驱动耕作方式变革</p><p style="text-align: justify;">　　气象墒情传感器、智能虫情测报站等设备如同“千里眼”，与空中无人机巡航、地面机器狗巡检形成立体监测网络。这是日前科技日报记者在北京市昌平区的天汇园果园见到的一幕。</p><p style="text-align: justify;">　　“目前，该果园环境和土壤墒情覆盖10余项指标，虫情识别准确率达90%，种植生产信息化率超过95%，同时土壤成分快检技术能在30分钟内完成土壤成分‘体检’，辅助实现果园虫情和灾情等早预警、早干预。”北京市智慧农业创新团队岗位专家吴建伟介绍，该果园管理从“经验驱动”转向“数据驱动”，为果树生长提供了全天候守护。</p><p style="text-align: justify;">　　在四川省成都市新都区稻菜现代农业园区，当地自主研发的农业巡检机器人已代替人工开展巡检工作；在浙江省衢州市龙游县田间地头，一架植保无人机3小时就能完成300亩农田的喷药流程，相当于40多个人整整一天的工作量……</p><p style="text-align: justify;">　　“十四五”以来，类似的农业新场景新模式不断涌现，现代农业设施装备持续普及应用。我国先后支持建设国家智慧农业创新应用项目116个，深入开展国产化智慧农业技术的中试熟化、推广应用，探索形成了一批信息技术与农机农艺相融合的节本增产增效技术模式。</p><p style="text-align: justify;">　　习近平总书记指出，农业科技创新要着力提升创新体系整体效能，农业科技工作要突出应用导向，把论文写在大地上。</p><p style="text-align: justify;">　　5年来，我国农业科技创新体系整体效能显著提升。我国充分利用物联网、大数据、人工智能等现代信息技术发展智慧农业，并研制出一批先进智能适用的农机装备。</p><p style="text-align: justify;">　　“随着智能农机加快推广，全国安装北斗终端的农机约200万台，植保无人机年作业面积超过4.1亿亩。人工智能、农业机器人等新技术与农业生产经营加速融合，精准播种、变量施肥、智慧灌溉、精准饲喂、环境控制等逐渐普及。”农业农村部市场与信息化司司长雷刘功介绍。</p><p style="text-align: justify;">　　这些前沿技术的落地应用，正是农业科技现代化推动农业现代化的生动实践。“十四五”以来，我国坚持用现代设施装备武装农业，用现代科学技术服务农业，推动农业现代化水平不断提高。2024年底，农业科技进步贡献率已经达到了63.2%，农作物耕种收综合机械化率超过75%。</p><p style="text-align: justify;">　　创新延“链”，拓宽食物供给版图</p><p style="text-align: justify;">　　近日，蒙牛集团携多款产品参加第八届中国国际进口博览会，展示其发展新质生产力的最新成果。“我们打造的全球液态奶行业首座‘灯塔工厂’，已成为全球乳业最高人效比的新标杆，是中国乳业抢占全球智能制造新高地的生动写照。”中粮集团副总经理、蒙牛乳业董事长庆立军介绍。这座“灯塔工厂”通过实施30多项第四次工业革命技术，实现了“百人百亿”的极致人效比——100名员工，年产能达百万吨，创造产值百亿元。</p><p style="text-align: justify;">　　今天，科研创新已成为发展现代化海洋牧场的强大引擎。南方海洋实验室研发“珠海琴”等多功能融合的新型组合式结构加强型养殖平台，为海洋养殖带来新变革；珠海市海洋集团形成海工型养殖装备设计、建造、施工和运维等全产业链条，成功研发“格盛一号”养殖平台，订单水体总量相当于新开拓28.25万亩耕地。</p><p style="text-align: justify;">　　习近平总书记指出，要树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系。</p><p style="text-align: justify;">　　“十四五”以来，我国突出科技支撑，强化要素保障，努力向森林要食物，向草原要食物，向江河湖海要食物，向设施农业要食物，向植物动物微生物要热量、要蛋白，多元化食物供给体系加快构建。</p><p style="text-align: justify;">　　一组数据表明，农业科技创新正通过看得见的方式，让老百姓的餐桌品类变得愈发丰富——2024年，我国肉蛋奶等畜产品总量达到1.75亿吨，比2020年增加2778万吨，增长18.8%；水产品总产量达到7358万吨，比2020年增长12.3%，水产品总产量持续36年居全球第一。</p><p style="text-align: justify;">　　党的二十届四中全会审议通过的《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出，“统筹发展科技农业、绿色农业、质量农业、品牌农业，把农业建成现代化大产业”。科技创新能够催生新产业、新模式、新动能，是发展新质生产力的核心要素。韩俊表示，加快建设农业强国，必须清醒认识到农业科技国际竞争新形势，把农业科技创新放在更加突出的位置，紧盯世界农业科技前沿，加快突破农业关键核心技术，努力抢占农业科技创新制高点，塑造农业农村发展新动能新优势，培育壮大农业新质生产力。</p>',NULL,2,100,'2024-06-02 22:55:25','“十四五”规划提出，完善农业科技创新体系，创新农技推广服务方式，建设智慧农业。5年来，在科技创新的强劲支撑下，14亿人的饭碗端得更牢、农业现代化水平显著提升、产业新动能持续增强，农业强国建设迈上新台阶。',100,'','2026-01-10 11:13:25',NULL);
INSERT INTO `sa_article` (`updated_by`,`delete_time`,`dept_id`,`tenant_id`,`content`,`cover_image`,`category`,`views`,`create_time`,`id`,`describe`,`tags`,`status`,`is_link`,`category_id`,`sort`,`link_url`,`is_hot`,`created_by`,`update_time`,`title`,`author`,`image`,`summary`) VALUES (1,NULL,3,1,'<p style="text-align: justify;"> &nbsp; &nbsp; &nbsp; &nbsp;可搭载7名乘客穿越卡门线，体验约4分钟失重体验……记者从11月22日在京开幕的第四届中国空间科学大会上了解到我国太空旅游的最新进展。与会专家学者认为，随着产业链条不断完善、核心技术持续突破，我国商业航天已迈入稳步快跑的发展新阶段，曾经遥不可及的“太空旅游”正加速走进现实。</p><p style="text-align: justify;">  记者在第四届中国空间科学大会同期举行的“航天新技术、新成果展”上看到，我国首型面向太空旅游的可重复使用飞行器力鸿二号的模型吸引了众多参观者。中科宇航展台工作人员告诉记者，力鸿二号将采用“箭船分离”的方式将乘客送上太空：飞到既定高度之后，载人舱与火箭分离，继续飞越100公里的卡门线，开始约4分钟的失重段，之后返回地面，以伞降的方式着陆，火箭也将垂直着陆回收。“我们的目标是让力鸿二号可重复使用超30次，这样就能把飞行成本降下来，让更多的人体验太空旅游。”</p><p style="text-align: justify;">  我国商业航天的快速发展让太空旅游渐行渐近。业界普遍认为，以可复用火箭为代表的核心技术突破是商业航天提速的关键支撑。据统计，2025年底至2026年初，我国可复用火箭技术将进入密集首飞期，包括蓝箭航天“朱雀三号”、中科宇航“力箭二号”、星际荣耀“双曲线三号”和星河动力“智神星一号”在内的多款可复用火箭将迎来首飞。</p><p style="text-align: justify;">  不仅火箭研制加速突破，卫星应用也在不断拓展。此次展会上，微纳星空等卫星企业也带来了最新的研发成果。微纳星空品牌总监刘晓光介绍，即将发射的“全天候卫士”MN200S-2（01B）星是公司自主研制的商业X波段相控阵雷达成像领域的技术标杆型卫星，可广泛应用于应急救灾、海洋维权、国土安全、生态监测、智慧城市建设等场景，并可实现多星高密度堆叠发射，为后续卫星规模化组网编队提供关键技术验证与工程实践依据。“随着国家低轨卫星互联网的能力建设牵引，微纳星空已经开启批量化、低成本的卫星制造。”</p><p style="text-align: justify;">  业界认为，目前我国已形成覆盖火箭研制、卫星制造、发射服务、地面应用的完整商业航天产业链，产业集群效应逐步显现。在北京，“南箭北星”的产业格局已显露雏形：亦庄新城正在打造全国首个商业航天共性科研生产基地——火箭大街，海淀区作为“北星”的核心承载区，已集聚涵盖商业卫星制造、测运控、运营及数据应用的近200家相关企业。“在此基础上，海淀正全力推进卫星小镇‘两区一平台’的建设：先导区目前已有40余家商业航天企业聚集；紧邻航天城的卫星小镇核心区54万平方米空间预计2026年6月竣备，将重点引入卫星上下游企业；同时，卫星小镇拟建公共服务平台，提供卫星整星及组部件的力学、热真空、抗辐射等多种测试服务。”卫星小镇核心区对接人段叶叶介绍。</p><p style="text-align: justify;">  “我国发展商业航天的优势是人多、力量大、竞争强，技术和产品能够快速迭代，紧跟国际趋势。”中国科学院微小卫星创新研究院副院长张永合在接受记者专访时表示，但目前我国商业航天企业和人才大多集中在制造领域，“还需要更多能创造任务的人，有非常前沿的想法，有改变当前航天模式的颠覆性路径。”</p><p style="text-align: justify;">  张永合认为，商业航天关键是要创造需求，“比如太空旅游就是商业航天创造的需求，将人们日常生活中的旅游延伸到太空中去，在产业上就属于增量。”未来，低空经济、空间互联网等也将打开想象空间。“有了坚实的技术底座，新的产业形态就会自然而然生长出来。”</p><p style="text-align: justify;">  不过，业内专家也指出，我国商业航天发展仍面临体制机制创新不足、部分核心技术有待突破等挑战。从政策层面来看，近年来国家持续加大对商业航天的支持力度，相关扶持政策和行业规范正在逐步完善，旨在优化市场环境、加大核心技术研发支持，为商业航天高质量发展营造良好生态，推动太空旅游等新业态逐步走向成熟。</p><p style="text-align: justify;">  业内普遍认为，商业航天已成为航天强国建设的重要增长点。从运载火箭重复使用技术突破到卫星应用场景拓展，随着技术持续成熟、产业链不断完善和政策环境优化，未来“上太空”有望从专业探索逐步走向大众体验，中国商业航天也将在全球太空经济格局中占据重要地位。</p><p><br></p>',NULL,NULL,1,'2024-06-02 22:56:47',2,'业界普遍认为，以可复用火箭为代表的核心技术突破是商业航天提速的关键支撑。据统计，2025年底至2026年初，我国可复用火箭技术将进入密集首飞期，包括蓝箭航天“朱雀三号”、中科宇航“力箭二号”、星际荣耀“双曲线三号”和星河动力“智神星一号”在内的多款可复用火箭将迎来首飞。',NULL,1,2,1,100,'',2,100,'2026-01-10 11:13:47','商业航天稳步快跑 “太空旅游”渐行渐近','新华网','https://www.news.cn/tech/20251124/c7cb9d4e405c4c82b78a8f861889cb22/20251124c7cb9d4e405c4c82b78a8f861889cb22_20251124044f95bbab864da2b0c30861aa41279b.png',NULL);
INSERT INTO `sa_article` (`sort`,`is_link`,`link_url`,`create_time`,`delete_time`,`describe`,`summary`,`cover_image`,`category`,`views`,`status`,`is_hot`,`update_time`,`category_id`,`title`,`dept_id`,`tenant_id`,`content`,`tags`,`id`,`created_by`,`updated_by`,`author`,`image`) VALUES (100,2,'','2024-06-02 22:58:41',NULL,'The Athletic报道，阿森纳理疗师乔丹-里斯即将加盟曼联，成为红魔的首席理疗师。曼联首席理疗师罗宾-萨德勒已于今年一月离开俱乐部',NULL,NULL,NULL,2,1,2,'2026-01-10 11:13:01',2,'以数字经济为引擎加快推进中国式现代化',12,1,'<p style="text-align: justify;"> &nbsp; &nbsp; &nbsp; &nbsp;随着中国式现代化不断向前推进，中国迎来了数字经济发展的新机遇。在数字经济快速发展的背景下，中国式现代化的内涵得以拓展，现代化动力得以重塑，现代化新动能得以培育，现代化新优势得以形成。数字技术创新、实体经济与数字经济融合、产业数字化、数字产业化成为推进中国式现代化的重要驱动力量。</p><p style="text-align: justify;">  在数字经济推动下，现代化由工业经济时代的现代化向数字经济时代的现代化转变，在这一大背景下需要在理论上研究数字经济赋能中国式现代化的逻辑和机制，需要深入探讨中国式现代化如何紧紧抓住数字经济发展带来的新机遇，以数字化的知识和信息作为关键生产要素，以数字技术为核心驱动力，在数据要素和数字技术的双轮驱动下推动中国式现代化走上新征程。</p><p style="text-align: justify;">  南京大学数字经济与管理学院任保平教授的专著《数字经济赋能中国式现代化》于2025年在江苏人民出版社出版，全书共17章，35.8万字。该书立足世界范围内数字化浪潮下的经济现代化背景，从理论与实践两个方面研究了数字经济发展对中国式现代化的赋能作用。</p><p style="text-align: justify;">  在理论层面，该书研究了数字经济发展对中国式现代化的影响、数字经济与中国式现代化的有机衔接，数字经济背景下中国式现代化目标的重塑、数字经济与中国式现代化深度融合的逻辑机制，数字经济背景下中国式现代化的延伸和拓展。在实践层面，从中国式现代化的不同方面具体研究了数字经济的赋能作用，具体包括数字经济赋能中国式新型工业化、新型城镇化、科技现代化、农业农村现代化、产业现代化和科技现代化。</p><p style="text-align: justify;">  该书的核心观点主要有以下方面。一是，中国式现代化战略在数字化转型背景下发生的一系列拓展。促进工业化与信息化的融合发展，以数字化带动工业化发展，加大数字技术研发力度，大力发展数字产业。以数字化带动农业现代化，补足中国式现代化短板。协同匹配数字经济时代的创新供求，提升产业技术创新能力。促进企业数字化转型，引领数字经济发展。协调产业数字化与数字产业化，推进产业基础现代化。加快新型基础设施建设，提升基础设施支撑能力。构建数字平台体系，打造现代化经济新形态。</p><p style="text-align: justify;">  二是，以数字经济发展培育中国式现代化新优势。针对数字经济带来的现代化新变化，研究了数字经济对中国式现代化的引擎作用，认为目前中国式现代化正处于数字经济蓬勃发展带来无数新机遇的时代，我们要抓住数字经济发展带来的新机遇，以数字经济推动中国式现代化的新发展。</p><p style="text-align: justify;">  三是，阐释数字经济赋能中国式现代化的逻辑。在理论上深刻阐释数字经济如何成为中国式现代化的新引擎，数字经济作为新引擎对中国式现代化赋能的驱动机制和路径，论证数字经济发展赋能中国式现代化在目标、路径和战略上的延伸和拓展，为数字经济赋能中国式现代化提供了一个理论框架。</p><p style="text-align: justify;">  四是，研究数字经济全面赋能中国式现代化的机制。中国式经济现代化涉及多方面内容，包括科技现代化、工业现代化、农业现代化、服务业现代化、产业链现代化、城市现代化、区域现代化、城市现代化、生态现代化、企业现代化、人的现代化和治理现代化，数字经济应该从上述方面赋能中国式现代化。</p><p style="text-align: justify;">  五是，提出了以数字经济培育中国式现代化新优势的路径。数字经济培育中国式现代化的新优势包括需求端的动力新优势、供给端的效率新优势等。需要从数字化转型的创新能力、基础设施的供给能力、数字化转型的战略支撑能力，数字化转型的保障能力等方面研究数字经济发展培育中国式现代化新优势的实现路径。而且，需要从效率变革机制、动力变革机制和质量变革机制等方面研究数字经济赋能中国式现代化新优势培育的机制，从数字产业化、产业数字化、产学研协同创新、劳动力质量和相关配套制度等方面实现数字经济培育中国式现代化的新优势，全面展示数字经济赋能中国式现代化中的应用场景。</p>',NULL,3,1,1,'新华网','https://www.news.cn/tech/20251023/0cb8f0bcb7874992b8d431abdd7331a9/202510230cb8f0bcb7874992b8d431abdd7331a9_2025102332abb363b12744eb9f725ce395f16e4a.png');
INSERT INTO `sa_article` (`summary`,`cover_image`,`tags`,`status`,`is_hot`,`create_time`,`delete_time`,`author`,`dept_id`,`describe`,`created_by`,`id`,`title`,`image`,`content`,`category`,`updated_by`,`category_id`,`tenant_id`,`views`,`sort`,`is_link`,`link_url`,`update_time`) VALUES (NULL,NULL,NULL,1,2,'2024-06-02 22:59:41',NULL,'新华网',8,'5月26日晚上18：00，中超第14轮，深圳新鹏城主场迎战上海申花，上半场马莱莱补射斩获赛季第6球，半场战罢，申花暂1-0新鹏城',1,4,'2025腾讯全球数字生态大会在深圳举行','https://www.news.cn/tech/20250918/a8a0f6e1a6d740188db7752e247518bb/20250918a8a0f6e1a6d740188db7752e247518bb_202509184f78f2904fa2456db9537d878cb89166.jpg','<p><br></p><div data-w-e-type="video" data-w-e-is-void>\n<video poster="" controls="true" width="auto" height="auto"><source src="https://vodpub6.v.news.cn/yqfbzx-original/20250918/20250918a8a0f6e1a6d740188db7752e247518bb_XxjfceC000090_20250917_CBVFN0A001.mp4" type="video/mp4"/></video>\n</div><p><span style="color: rgb(0, 0, 0);"> &nbsp; &nbsp; &nbsp; &nbsp;9月16日，2025腾讯全球数字生态大会在深圳举行，会上公布多项AI技术和产品最新进展，并宣布全面开放腾讯AI落地能力及优势场景，助力“好用的AI”在千行百业中加速落地。</span></p><p><br></p>',NULL,1,2,2,3,100,2,'','2026-01-10 13:42:34');
INSERT INTO `sa_article` (`tenant_id`,`content`,`cover_image`,`created_by`,`update_time`,`id`,`title`,`author`,`dept_id`,`tags`,`status`,`describe`,`category`,`views`,`is_link`,`link_url`,`updated_by`,`create_time`,`delete_time`,`category_id`,`image`,`summary`,`sort`,`is_hot`) VALUES (1,'<p><br></p><div data-w-e-type="video" data-w-e-is-void>\n<video poster="https://vodpub6.v.news.cn/yqfbzx-original/20260109/image/2ff2c0d5-4060-400d-8640-b41a0da5af1f.jpg" controls="true" width="360" height="640"><source src="https://vodpub6.v.news.cn/yqfbzx-original/20260109/20260109896bd0b56c18435987243f0f5dc01d67_XxjfceC000165_20260109_CBVFN0A001.mp4" type="video/mp4"/></video>\n</div><p style="text-align: left;"><span style="color: rgb(0, 0, 0);"> &nbsp; &nbsp; &nbsp; &nbsp;2026年美国拉斯维加斯消费电子展（CES）6日至9日举行，首次亮相海外展会的中国小机器人“启元Q1”刚一登场就成为焦点，凭借其出色表现“圈粉”海外。</span></p>',NULL,1,'2026-01-10 13:42:24',5,'秀我中国丨中国小机器人“勇闯”美国CES','新华网',121,NULL,1,'2026年美国拉斯维加斯消费电子展（CES）6日至9日举行，首次亮相海外展会的中国小机器人“启元Q1”刚一登场就成为焦点，凭借其出色表现“圈粉”海外。',NULL,3,2,'',1,'2024-06-02 23:01:17',NULL,3,'https://www.news.cn/tech/20260109/b2c43e2b0d1e43a98840c33e37fbbc73/20260109896bd0b56c18435987243f0f5dc01d67_202601099d0953f9999949a9b55e9d212d7bf773.jpg',NULL,100,2);
INSERT INTO `sa_article` (`category_id`,`author`,`tenant_id`,`content`,`status`,`delete_time`,`id`,`title`,`dept_id`,`describe`,`summary`,`cover_image`,`sort`,`link_url`,`category`,`tags`,`views`,`is_hot`,`created_by`,`updated_by`,`create_time`,`update_time`,`image`,`is_link`) VALUES (3,'新华网',1,'<p><span style="color: rgb(0, 0, 0);"> &nbsp; &nbsp; &nbsp; &nbsp;1月9日，清华大学智能产业研究院（AIR）联合清华大学生命学院、清华大学化学系在《科学》杂志发表论文《深度对比学习实现基因组级别药物虚拟筛选》。该论文研发了一个AI驱动的超高通量药物虚拟筛选平台DrugCLIP, 筛选速度对比传统方法实现百万倍提升，同时在预测准确率上也取得显著突破。依托该平台，团队打通了从AlphaFold结构预测到药物发现的关键通道，首次完成了覆盖人类基因组规模的药物虚拟筛选，为后AlphaFold时代的创新药物发现带来新可能性。</span></p><p><img src="https://www.news.cn/tech/20260109/2e0f65d6733a4e2588a97dfe96593a09/202601092e0f65d6733a4e2588a97dfe96593a09_2026010932fb993ce4734583aa3e4e861e536cff.png" alt="" data-href="" style=""/></p><p style="text-align: justify;"> &nbsp; &nbsp;长期以来，药物研发面临“高风险、高投入、低成功率”的难题，在靶点发现与先导化合物筛选阶段，受限于传统工具的计算能力，绝大多数潜在靶点和化合物仍未被充分探索。如何在广阔的生物与化学空间中精准高效地发现活性化合物，是当前创新药物研发面临的核心挑战。</p><p style="text-align: justify;">  据了解，为突破虚拟筛选规模瓶颈，DrugCLIP创新性地构建了蛋白口袋与小分子的“向量化结合空间”，将传统基于物理对接的筛选流程转化为高效的向量检索问题。该模型结合对比学习、3D结构预训练与多模态编码技术，能在三维结构层面精准建模蛋白-配体间的相互作用。训练后的高潜力分子将自然聚集于目标蛋白口袋的向量邻域，能够有效支撑快速的大规模虚拟筛选。依托这一机制，DrugCLIP在128核CPU+8张GPU的计算节点上，能实现毫秒级打分与万亿级日吞吐能力，筛选100万个候选分子仅需0.02秒，日处理能力达31万亿次，对比传统方法实现了百万倍提升。</p><p style="text-align: justify;"><img src="https://www.news.cn/tech/20260109/2e0f65d6733a4e2588a97dfe96593a09/202601092e0f65d6733a4e2588a97dfe96593a09_2026010902fd55e1493f4741a2f10b4480ee398e.png" alt="" data-href="" style=""></p><p style="text-align: justify;"> &nbsp; &nbsp;团队与清华大学闫创业教授团队合作，在去甲肾上腺素转运体（NET）的临床相关靶点上开展了系列生物实验验证。团队使用DrugCLIP模型从160万个候选分子中筛选出约100个高评分分子，同位素配体转运实验检测显示，其中15%为有效抑制剂，其中12个分子结合能力优于现有抗抑郁药物安非他酮。相关复合物结构已通过冷冻电镜解析，进一步验证了DrugCLIP筛选结果的生物学可信度。</p><p style="text-align: justify;">  值得关注的是，DrugCLIP支持对AlphaFold预测的蛋白结构和apo（无配体）状态下的蛋白口袋进行筛选，扩大了其在真实药物发现场景中的适用性。团队和清华大学刘磊教授团队合作，针对E3泛素连接酶TRIP12（thyroid hormone receptor interactor 12）进行了虚拟筛选与实验验证。过往研究发现，TRIP12是多种肿瘤、帕金森综合征的潜在靶点，但是TRIP12缺少已知的小分子配体和复合物结构。团队使用DrugCLIP模型，从160万个候选分子中高通量筛选出约50个高评分分子，SPR实验证实，其中10个分子与TRIP12有结合能力，两个亲和力较高的分子也对TRIP12的泛素连接酶活性有一定的抑制活性。</p><p style="text-align: justify;">  此外，依托DrugCLIP，团队首次完成了人类基因组规模的虚拟筛选项目，覆盖约1万个蛋白靶点、2万个结合口袋，分析超过5亿个小分子，富集出200万余个高潜力活性分子，构建了目前已知最大规模的蛋白-配体筛选数据库。该数据库已面向全球科研社区开放，为基础研究与早期药物发现提供了强大数据支持。</p><p style="text-align: justify;">  DrugCLIP平台现已免费开放，用户无需本地部署，通过网页上传蛋白结构即可启动筛选任务。平台集成口袋/分子编码、向量检索、可视化与结果分析等功能，支持多种分子库调用与自定义上传，广泛适用于科研机构与企业用户。</p><p style="text-align: justify;">  未来，DrugCLIP将与科研产业生态合作伙伴深度合作，在抗癌、传染病、罕见病等方向加速新靶点与First-in-class药物的发现。团队将持续优化引擎性能、拓展支持模态，助力构建一个更智能、高效与普惠的全球药物创新生态。</p>',1,NULL,6,'AI助力药物虚拟筛选提速百万倍 开启后AlphaFold时代创新药',1,'团队与清华大学闫创业教授团队合作，在去甲肾上腺素转运体（NET）的临床相关靶点上开展了系列生物实验验证。',NULL,NULL,100,'',NULL,NULL,4,2,1,1,'2024-06-02 23:02:40','2026-01-10 13:38:51','https://www.news.cn/tech/20260109/2e0f65d6733a4e2588a97dfe96593a09/202601092e0f65d6733a4e2588a97dfe96593a09_202601090012b088f5604e22a77ae70f8656f466.jpg',2);
INSERT INTO `sa_article` (`tags`,`sort`,`status`,`created_by`,`id`,`category_id`,`title`,`dept_id`,`image`,`describe`,`views`,`updated_by`,`author`,`content`,`summary`,`is_link`,`link_url`,`delete_time`,`tenant_id`,`cover_image`,`is_hot`,`create_time`,`update_time`,`category`) VALUES (NULL,100,1,1,7,4,'高度重视低空经济为哪般',4,'https://www.news.cn/tech/20250312/c0453593a495424780c5424c054a1d4d/20250312c0453593a495424780c5424c054a1d4d_2025031215d8945b560d4d169997f7745d0ef56f.jpg','当前，我国低空经济正处于市场培育初期，关键技术的实用性和商业价值仅得到初步验证，但已彰显出广阔的增长空间',11,1,'新华网','<p style="text-align: justify;"> &nbsp; &nbsp; &nbsp; &nbsp;近年来，低空经济成为全球发达经济体角逐的重要方向。虽然世界范围内低空经济还处于培育初期阶段，但是美国、日本、欧盟等国家和地区已经重点围绕场景开发应用、交通管理能力、运行技术验证、系统标准体系等方面积极出台和完善相关政策，加快发展低空经济。</p><p style="text-align: justify;">  低空经济是依托低空飞行活动牵引串联的一系列相互关联的产业经济活动，不仅包括上游生产制造飞行器所必需的材料、零部件及分系统的行业企业，还包括中下游低空飞行器组装集成制造和测试试飞、设施配套及低空服务等领域。低空经济产业链条长、产业关联性强、应用场景丰富，具有战略引领性、高增长潜力等显著特征，既可以推动现代农牧业、先进制造业、现代服务业深度融合发展，又能够扩大有效投资、提振消费需求、提升创新能力。世界主要国家高度重视低空经济发展，就是因为看好其发展前景。</p><p style="text-align: justify;">  当前，我国低空经济正处于市场培育初期，关键技术的实用性和商业价值仅得到初步验证，但已彰显出广阔的增长空间。未来随着技术迭代升级和商业模式逐步成熟，低空经济的高增长潜力将会进一步释放，更容易实现相关产业企业的群体性爆发成长，有望成为拉动经济增长的新引擎。</p><p style="text-align: justify;">  一方面，低空飞行器的产业规模体量加快增长、产业生态持续完善。目前，我国无人机制造国际竞争力逐步增强，消费级无人机世界领先优势突出。截至2023年底，我国民用无人机研制企业已超过2300家，量产的无人机产品超过1000款。2023年，我国民用无人机产业规模达到1174.3亿元，同比增长32%。同时，新一代信息技术、新材料、新能源加速与航空科学技术融合发展，推动低空飞行器动力装备及系统、传感器、飞控系统等相关技术加速迭代，绿色高效、安全低噪的飞行器设计、制造与验证技术也持续更新升级。</p><p style="text-align: justify;">  另一方面，体量巨大、类型多样的应用场景持续涌现，牵引低空服务快速释放动能。运营航空器大幅增加，《2023—2024中国民用无人驾驶航空发展报告》显示，截至2024年8月底，我国无人机实名登记数达198.7万架，比2023年底增加72万架；共颁发无人机驾驶员执照22万本，比2023年底增加13.9%。随着影视航拍、航空运动、空中观光游览等低空文旅应用场景快速发展，低空经济能为满足人民群众美好生活需求提供新供给。2023年，横店“航空＋影视＋旅游”交旅融合案例入选第一批交通运输与旅游融合发展十佳案例；2024年，敦煌“飞天”通用航空项目等航空旅游产品案例入选第二批交通运输与旅游融合发展示范案例。低空旅游市场潜力开始显现。</p><p style="text-align: justify;">  同时，低空经济在农业植保、现代物流等行业领域的发展应用不断深入。随着无人机应用技术不断成熟和应用场景持续丰富，“农林牧副渔”多场景作业不断拓展，农业无人机服务市场规模呈蓬勃发展态势。2024年，全国植保无人机的保有量达到25.1万架，作业面积更是高达26.7亿亩次，同比增长近25%。从全球看，上世纪80年代以来，美国农业植保无人机作业渗透率超过50％，日本60％的稻田采用无人机进行植保作业。相较而言，我国农业无人机作业渗透率还比较低，有很大发展空间。在低空物流领域，以无人机为载运工具的无人化配送成为优化城市物流的重要方向，这能有效解决传统物流配送模式面临的劳动力成本、运输成本大幅攀升以及物资配送流通效率低下等诸多问题。在“低空+”领域，低空经济赋能社会治理成效突出，促进巡检、应急救援、城市管理、森林防火、医疗救护等公共服务快速发展。实践中，北京延庆、湖北武汉等地已采用电力线路无人机智能巡检，有效降低了巡检成本，提升了巡检效率。</p><p style="text-align: justify;">  但也要看到，我国低空经济发展还存在一些问题，如统筹发展和安全有短板、产业融合化发展不足、空域管理协同机制尚不健全、基础设施建设相对滞后等。对此，要从突出集群融合、强化科技创新、加强设施建设等方面综合施策，将低空经济的发展潜力充分释放出来。</p><p style="text-align: justify;">  一是突出集群融合，加快培育壮大低空经济产业集群，以市场需求为牵引、以科技创新为驱动，积极完善产业生态、谋划应用场景，推进低空制造业集群化发展。二是强化科技创新，聚焦低空经济创新链薄弱环节，加大科技创新投入，加快提升低空技术支撑能力。三是加强设施建设，构建低空经济基础设施综合保障体系，坚持绿色发展、节约集约，统筹推进通用机场、电动垂直起降飞行器起降场、固定运营基地、飞行服务站等地面配套基础设施建设，推进低空飞行通信、导航、气象监测等信息基础设施建设，加速低空经济智联网络设施建设。此外，还要统筹发展和安全，加强低空飞行器监控防护，强化低空安全技术攻关，提升空域精细化管理能力。坚持包容审慎的安全风险管控理念，建设监管服务体系，建立灵活调配、动态高效的低空空域管理使用机制，增强管理的协同性与联动性。</p>',NULL,2,'',NULL,1,NULL,2,'2024-06-02 23:04:23','2026-01-10 13:43:44',NULL);
INSERT INTO `sa_article` (`content`,`category`,`create_time`,`delete_time`,`category_id`,`dept_id`,`status`,`is_link`,`is_hot`,`tags`,`title`,`describe`,`summary`,`sort`,`link_url`,`updated_by`,`id`,`cover_image`,`created_by`,`update_time`,`views`,`author`,`tenant_id`,`image`) VALUES ('<p style="text-align: justify;"> &nbsp; &nbsp; &nbsp; 记者从国家发展和改革委员会官方网站获悉，低空经济发展司已正式成立。</p><p style="text-align: justify;">　　低空经济发展司的具体职责是拟订并组织实施低空经济发展战略、中长期发展规划，提出有关政策建议，协调有关重大问题等。</p><p style="text-align: justify;">　　近日，低空经济发展司召开推动低空基础设施建设座谈会和推动低空智能网联系统建设专题座谈会。</p><p style="text-align: justify;">　　在推动低空基础设施建设座谈会上，低空经济发展司负责同志同自然资源部、生态环境部等部委和有关中央企业进行座谈，了解相关领域低空经济典型场景应用和相关基础设施建设发展情况，并就推动低空基础设施有序规划建设进行交流。</p><p style="text-align: justify;">　　在推动低空智能网联系统建设专题座谈会上，低空经济发展司负责同志与通信、导航方面有关专家进行座谈，就低空智能网联系统建设进行交流。</p>',NULL,'2024-06-02 23:04:23',NULL,4,1,1,2,2,NULL,'国家发改委成立低空经济发展司','近日，低空经济发展司召开推动低空基础设施建设座谈会和推动低空智能网联系统建设专题座谈会..',NULL,100,'',1,8,NULL,1,'2026-04-23 23:21:09',6,'新华网',1,'https://www.news.cn/tech/20241231/3f5396024a9749ee863292c04c7119dc/202412313f5396024a9749ee863292c04c7119dc_2024123101c42d384b83467f835ffd286af095d4.jpg');
INSERT INTO `sa_article` (`image`,`tags`,`link_url`,`is_hot`,`update_time`,`delete_time`,`author`,`dept_id`,`category`,`views`,`sort`,`status`,`id`,`title`,`content`,`summary`,`is_link`,`created_by`,`updated_by`,`category_id`,`tenant_id`,`describe`,`cover_image`,`create_time`) VALUES ('http://127.0.0.1:8000/uploads/2026/03/28/69c7a3b2058589.44968839.webp',NULL,'',2,'2026-04-23 23:21:00',NULL,'admin',1,NULL,0,100,1,9,'多租户系统架构与权限设计探讨','<p>多租户系统架构与权限设计探讨多租户系统架构与权限设计探讨</p><p>多租户系统架构与权限设计探讨</p><p>多租户系统架构与权限设计探讨</p>',NULL,2,1,1,1,2,'多租户系统架构与权限设计探讨',NULL,'2026-04-23 22:22:26');
INSERT INTO `sa_article` (`link_url`,`created_by`,`update_time`,`delete_time`,`category`,`dept_id`,`sort`,`status`,`is_hot`,`updated_by`,`create_time`,`title`,`author`,`cover_image`,`tags`,`id`,`category_id`,`tenant_id`,`image`,`describe`,`content`,`summary`,`is_link`,`views`) VALUES ('',1,'2026-06-21 19:39:42',NULL,NULL,1,100,1,2,1,'2026-04-23 23:39:01','切尔西官宣41岁主帅下课！带队107天+英超遭5连败 解约金1200万镑','admin',NULL,NULL,10,2,2,'http://127.0.0.1:8000/uploads/2026/03/28/69c7a3acd6b581.21163358.png','切尔西官宣41岁主帅下课！带队107天+英超遭5连败 解约金1200万镑','<p><br></p><p style="text-align: justify;">北京时间4月23日，英超豪门切尔西俱乐部官方宣布，因近期比赛结果和球队表现未能达到应有标准，41岁的主帅罗塞尼尔正式下课。</p><p style="text-align: justify;">切尔西官方向罗塞尼尔及其教练组，在俱乐部效力期间所付出的所有努力，表示衷心的感谢，并祝愿他在未来一切顺利。</p><p style="text-align: center;"><img src="https://nimg.ws.126.net/?url=http%3A%2F%2Fdingyue.ws.126.net%2F2026%2F0423%2Fd77d2db1j00tdwmbr00p7d000qo00gcm.jpg&amp;thumbnail=660x2147483647&amp;quality=80&amp;type=jpg" alt="" data-href="" style=""><br><br></p><p style="text-align: justify;">切尔西还同时宣布，助教卡勒姆·麦克法兰将担任一线队临时主教练，带领球队直至本赛季结束，并由俱乐部现有教练组成员协助。</p><p style="text-align: justify;">切尔西官方还表示，俱乐部未来会在寻求新帅稳定人选的过程中，进行自我反思，以做出正确的长期任命。</p><p style="text-align: center;"><img src="https://nimg.ws.126.net/?url=http%3A%2F%2Fdingyue.ws.126.net%2F2026%2F0423%2Fc5090293j00tdwmbr008dd000qo00g8m.jpg&amp;thumbnail=660x2147483647&amp;quality=80&amp;type=jpg" alt="" data-href="" style=""><br><br></p><p style="text-align: justify;">今年1月8日，罗塞尼尔从清湖集团旗下的另一支球队斯特拉斯堡，“内部调遣”来到切尔西，双方签下了长达6年半的合同。</p><p style="text-align: justify;">上任之初，他带领切尔西踢出了不错的成绩，前9场比赛球队只在英联杯两负阿森纳，赢下了剩余7场。</p><p style="text-align: center;"><img src="https://nimg.ws.126.net/?url=http%3A%2F%2Fdingyue.ws.126.net%2F2026%2F0423%2F52e72206j00tdwmbq0017d000qo00hmm.jpg&amp;thumbnail=660x2147483647&amp;quality=80&amp;type=jpg" alt="" data-href="" style=""><br><br></p><p style="text-align: justify;">但随后，切尔西的状况开始急转直下，最近8场比赛，切尔西1胜7负，唯一的一胜还是在足总杯赛场战胜第三级别联赛球队维尔港。</p><p style="text-align: justify;">最近5场联赛，切尔西遭遇5连败且一球未进，目前切尔西在本轮先赛的情况下，已经落后欧冠区7分之多。</p><p style="text-align: justify;">最终，罗塞尼尔仅执教切尔西107天后，便黯然下课。他带队打了23场比赛，战绩为11胜2平10负，胜率不到5成。</p><p style="text-align: center;"><img src="https://nimg.ws.126.net/?url=http%3A%2F%2Fdingyue.ws.126.net%2F2026%2F0423%2F869822dfj00tdwmbr00bbd000e600hvm.jpg&amp;thumbnail=660x2147483647&amp;quality=80&amp;type=jpg" alt="" data-href="" style=""><br><br></p><p style="text-align: justify;">而据多家媒体确认，罗塞尼尔在切尔西剩余未被支付的薪水高达2400万镑。而队报记者表示，切尔西不会支付所有剩余款项，将支付1000万-1200万镑解雇他。</p><p style="text-align: justify;"><br></p>',NULL,2,0);
INSERT INTO `sa_article` (`link_url`,`update_time`,`delete_time`,`title`,`dept_id`,`content`,`category`,`created_by`,`create_time`,`id`,`author`,`describe`,`summary`,`tags`,`is_hot`,`category_id`,`cover_image`,`is_link`,`updated_by`,`tenant_id`,`image`,`views`,`sort`,`status`) VALUES ('','2026-08-28 21:28:31',NULL,'Dromara Warm-Flow，国产的工作流引擎1',1,'<blockquote style="text-align: start;">Dromara Warm-Flow，国产的工作流引擎，以其简洁轻量、五脏俱全、灵活扩展性强的特点，成为了众多开发者的首选。它不仅可以通过jar包快速集成设计器，同时原生支持经典和仿钉钉双模式，还具备以下显著优势：</blockquote><ul><li style="text-align: start;"><strong>简洁易用</strong>‌：仅包含7张表，代码量少，上手和集成速度快。</li><li style="text-align: start;"><strong>审批功能全面</strong>‌：支持通过、退回、撤销、拿回、任意跳转、终止、转办、票签、委派和加减签、互斥、并行、自动审批、远程访问和脚本执行服务等多种审批操作，以及条件表达式、办理人表达和监听器等高级功能。</li><li style="text-align: start;"><strong>流程设计器</strong>‌：通过jar包形式快速集成到项目，支持节点属性扩展，原生支持经典和仿钉钉双模式。</li><li style="text-align: start;"><strong>流程图</strong>‌：自带流程图，通过jar包快速集，功能扩展，原生支持经典和仿钉钉双模式。</li><li style="text-align: start;"><strong>条件表达式</strong>‌：内置常见的和spel条件表达式，支持自定义扩展。</li><li style="text-align: start;"><strong>办理人变量表达式</strong>‌：内置${handler}和spel格式的表达式，满足不同场景需求，灵活可扩展。</li><li style="text-align: start;"><strong>监听器</strong>‌：提供四种监听器，支持不同作用范围和spel表达式，参数传递灵活，支持动态权限。</li><li style="text-align: start;"><strong>流程变量</strong>‌：在整个流程办理过程起到重要的角色，如办理人表达式中，传入变量进行动态指定办理人。</li><li style="text-align: start;"><strong>ORM框架支持</strong>‌：支持MyBatis、Mybatis-Plus、Mybatis-Flex、Jpa、Easy-Query和BeetlSql，后续将扩展支持其他框架</li><li style="text-align: start;"><strong>数据库支持</strong>‌：支持MySQL、Oracle、PostgreSQL和SQL Server，其他数据库只需要转换表结构即可支持。</li><li style="text-align: start;"><strong>多租户与软删除</strong>‌：流程引擎自身维护多租户和软删除实现，也可使用对应ORM框架的实现方式。</li><li style="text-align: start;"><strong>兼容性</strong>‌：同时支持Spring和Solon，兼容Java8、Java17、Java21。</li><li style="text-align: start;"><strong>实战项目</strong>‌：官方提供基于Ruoyi-Vue封装的实战项目，极具参考价值。</li><li style="text-align: start;"></li><li style="text-align: start;"> <a href="https://www.warm-flow.com/master/introduction/introduction.html" target="_blank">https://www.warm-flow.com/master/introduction/introduction.html</a> </li><li style="text-align: start;"> <a href="https://juejin.cn/post/7205873584339009596" target="_blank">https://juejin.cn/post/7205873584339009596</a> </li></ul>',NULL,1,'2026-04-26 17:09:16',11,'Dromara','Dromara Warm-Flow，国产的工作流引擎，以其简洁轻量、五脏俱全、灵活扩展性强的特点，成为了众多开发者的首选。它不仅可以通过jar包快速集成设计器，同时原生支持经典和仿钉钉双模式，还具备以下显著优势：',NULL,NULL,2,2,NULL,2,1,1,'http://127.0.0.1:8000/uploads/2026/03/28/69c7a3af23d945.66099869.webp',0,100,1);
