INSERT INTO `sa_system_oper_log` (`delete_time`,`id`,`method`,`username`,`service_name`,`ip`,`remark`,`created_by`,`app`,`ip_location`,`update_time`,`router`,`request_data`,`duration`,`updated_by`,`create_time`) VALUES (NULL,177,'PUT','admin','update','127.0.0.1',NULL,1,'system','','2026-08-28 21:28:31','/api/article/update/11','{"_raw": "{\\"id\\":11,\\"title\\":\\"Dromara Warm-Flow，国产的工作流引擎1\\",\\"category_id\\":2,\\"author\\":\\"Dromara\\",\\"image\\":\\"http://127.0.0.1:8000/uploads/2026/03/28/69c7a3af23d945.66099869.webp\\",\\"describe\\":\\"Dromara Warm-Flow，国产的工作流引擎，以其简洁轻量、五脏俱全、灵活扩展性强的特点，成为了众多开发者的首选。它不仅可以通过jar包快速集成设计器，同时原生支持经典和仿钉钉双模式，还具备以下显著优势：\\",\\"content\\":\\"<blockquote style=\\\\\\"text-align: start;\\\\\\">Dromara Warm-Flow，国产的工作流引擎，以其简洁轻量、五脏俱全、灵活扩展性强的特点，成为了众多开发者的首选。它不仅可以通过jar包快速集成设计器，同时原生支持经典和仿钉钉双模式，还具备以下显著优势：</blockquote><ul><li style=\\\\\\"text-align: start;\\\\\\"><strong>简洁易用</strong>‌：仅包含7张表，代码量少，上手和集成速度快。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>审批功能全面</strong>‌：支持通过、退回、撤销、拿回、任意跳转、终止、转办、票签、委派和加减签、互斥、并行、自动审批、远程访问和脚本执行服务等多种审批操作，以及条件表达式、办理人表达和监听器等高级功能。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>流程设计器</strong>‌：通过jar包形式快速集成到项目，支持节点属性扩展，原生支持经典和仿钉钉双模式。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>流程图</strong>‌：自带流程图，通过jar包快速集，功能扩展，原生支持经典和仿钉钉双模式。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>条件表达式</strong>‌：内置常见的和spel条件表达式，支持自定义扩展。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>办理人变量表达式</strong>‌：内置${handler}和spel格式的表达式，满足不同场景需求，灵活可扩展。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>监听器</strong>‌：提供四种监听器，支持不同作用范围和spel表达式，参数传递灵活，支持动态权限。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>流程变量</strong>‌：在整个流程办理过程起到重要的角色，如办理人表达式中，传入变量进行动态指定办理人。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>ORM框架支持</strong>‌：支持MyBatis、Mybatis-Plus、Mybatis-Flex、Jpa、Easy-Query和BeetlSql，后续将扩展支持其他框架</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>数据库支持</strong>‌：支持MySQL、Oracle、PostgreSQL和SQL Server，其他数据库只需要转换表结构即可支持。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>多租户与软删除</strong>‌：流程引擎自身维护多租户和软删除实现，也可使用对应ORM框架的实现方式。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>兼容性</strong>‌：同时支持Spring和Solon，兼容Java8、Java17、Java21。</li><li style=\\\\\\"text-align: start;\\\\\\"><strong>实战项目</strong>‌：官方提供基于Ruoyi-Vue封装的实战项目，极具参考价值。</li><li style=\\\\\\"text-align: start;\\\\\\"></li><li style=\\\\\\"text-align: start;\\\\\\"> <a href=\\\\\\"ht','71.15',NULL,'2026-08-28 21:28:31');
